package com.imagine.martinhost;

import java.util.*;

/** Offline, deterministic rounds: no fabricated AI scores or remote assets. */
public final class PartyGames {
 public static final class Round {
  public final String question,answer; public final boolean judged;
  Round(String q,String a,boolean j){question=q;answer=a;judged=j;}
 }
 public static final class Game {
  public final String id,title,rules,example; public final List<Round> rounds;
  Game(String i,String t,String r,String e,Round... rs){id=i;title=t;rules=r;example=e;rounds=Arrays.asList(rs);}
 }
 private static Round q(String q,String a){return new Round(q,a,false);}
 private static Round j(String q){return new Round(q,"",true);}
 private static Round j(String q,String a){return new Round(q,a,true);}
 public static List<Game> all(){return Arrays.asList(
  new Game("chgk","Что? Где? Когда?","Обсудите вопрос. Скажите «ответ» и ваш вариант. Верный ответ — один балл. Можно попросить ответ или пропустить.","Что можно нарушить без прикосновения? Обещание.",
   q("Что становится больше, если из него убирать землю?","яма|яму"),q("Два отца и два сына съели три яблока, по одному каждый. Как?","дед|дедушка"),q("Вы обогнали бегуна на втором месте. На каком месте вы теперь?","втором|второе|2"),q("В комнате четыре угла. В каждом сидит кот. Напротив каждого — три кота. Сколько всего котов?","четыре|4"),q("Какой месяц содержит двадцать восемь дней?","каждый|все|любой"),q("У палки два конца. Сколько концов у трёх с половиной палок?","восемь|8")),
  new Game("melody","Угадай мелодию","Нужны треки, добавленные в разделе «Музыка». Играет шестисекундный отрывок. Назовите песню или исполнителя после слова «ответ». Один балл за совпадение. В имени файла должны быть исполнитель и название.","Если звучит знакомая песня группы Руки Вверх, можно ответить названием группы."),
  new Game("time_machine","Музыкальная машина времени","Играет отрывок вашего трека. Назовите год или десятилетие после слова «ответ». Год берётся только из названия файла: добавьте его заранее. Один балл за ответ.","Для песни с годом 1998 подходит ответ «девяностые»."),
  new Game("two_stars","Две звезды в одном лице — словами","Это версия без готовых фотоколлажей. Я даю два описания, вы называете обеих звёзд. По одному баллу за раунд; ответ подтверждает организатор кнопкой «Засчитать».","Волшебник с молнией и сыщик с Бейкер-стрит: Гарри Поттер и Шерлок Холмс.",
   j("Один герой — пират Джек Воробей, другой — железный супергерой Тони Старк. Назовите обоих актёров.","Джонни Депп и Роберт Дауни-младший"),j("Первая поёт «Знаешь ли ты», второй — «Крошка моя». Назовите обоих исполнителей.","МакSим и Сергей Жуков"),j("Один — Терминатор, второй — Рокки. Назовите обоих актёров.","Арнольд Шварценеггер и Сильвестр Сталлоне")),
  new Game("quotes","Кто сказал эту цитату?","Угадайте литературного героя. Скажите «ответ» и имя. Один балл за верный ответ.","«Быть или не быть?» — Гамлет.",
   q("«А судьи кто?»","чацкий"),q("«Счастливые часов не наблюдают». Кто говорит это в «Горе от ума»?","софья|софия"),q("«Ребята! не Москва ль за нами?» Кто произносит это в стихотворении «Бородино»?","полковник"),q("«А Васька слушает да ест». О каком животном речь?","кот|кошка")),
  new Game("naughty_rhyme","Испорченные стишки","Авторские рифмы с невинными ответами. Закончите строку. Не спешите с первым словом! Один балл за точный ответ.","Без одежды круглый год у калитки дуб растёт. Ответ — дуб.",
   q("Вечер, свечи, тишина. Вдруг на кухне — ветчина! Кто утащил её со стола? Не любовник, а…","кот|кота"),q("Он горячий, он большой, мы несём его домой. Всем достанется кусок: это праздничный…","пирог"),q("За занавеской кто-то ждёт, хвостом по полу тихо бьёт. Пушистый маленький живот — пришёл на праздник рыжий…","кот"),q("Мы всю ночь вдвоём не спали, всё бросали и считали. На столе звенели кости, в дом пришли весёлые…","гости")),
  new Game("impostor","Звёздный самозванец","Один игрок тайно получает роль знаменитости, говорит от её имени тридцать секунд. Гости угадывают. Организатор подтверждает ответ кнопкой «Засчитать». Не имитируем голос и не высмеиваем внешность.","Игрок говорит про космос и первый полёт. Это может быть Юрий Гагарин.",
   j("Организатор, шепните игроку имя известного музыканта. Игрок, представьтесь без имени и названий песен. У гостей три вопроса."),j("Новый игрок получает роль известного спортсмена. Опишите свой обычный день без названия спорта."),j("Теперь роль — знаменитый персонаж кино. Расскажите, что лежит у вас в карманах.")),
  new Game("transform","Что AI сделал со звездой? — импровизация","Версия без подготовленных картинок. Организатор тайно называет знаменитость и необычную профессию. Игрок изображает рабочий день, остальные угадывают. Балл подтверждает организатор.","Воображаемый рок-музыкант стал библиотекарем и просит тишины.",j("Секретная знаменитость теперь повар на космической станции. Покажите тридцать секунд её работы."),j("Следующая знаменитость стала экскурсоводом в вашем городе. Начните экскурсию."),j("Третья знаменитость работает продавцом зонтов в пустыне. Убедите нас купить зонт.")),
  new Game("movie_ai","AI сломал фильм — словами","Я пересказываю известный сюжет как бытовую проблему. Вы угадываете фильм после слова «ответ». Один балл за ответ.","Мальчик не успел на семейную поездку и занялся охраной дома: «Один дома».",q("Юноша узнаёт, что его обычная жизнь — компьютерная симуляция, и выбирает красную таблетку.","матрица"),q("Компания ищет способ донести ювелирное изделие до вулкана, хотя проще было бы не брать его.","властелин колец"),q("Пассажиры роскошного судна обнаруживают, что у айсберга нет службы поддержки.","титаник"),q("Огр идёт решать жилищный вопрос и возвращается с принцессой.","шрек")),
  new Game("expert","Объяснение эксперта","Игрок тридцать секунд серьёзно объясняет абсурдную ситуацию. Не перебиваем. Организатор присуждает один балл за выполненное выступление.","Почему чайник требует отпуск? Потому что весь год работал под давлением.",j("Вы эксперт. Почему холодильник решил стать фитнес-тренером?"),j("Объясните, почему будильники собираются в тайный профсоюз."),j("Докажите, что потерянные носки организовали своё государство.")),
  new Game("ai_court","AI-суд","Три добровольца: обвиняемый, адвокат, прокурор. Каждому по тридцать секунд. Обвинения только выдуманные. Организатор может дать балл участнику. После каждой речи скажите «дальше».","Обвинение: человек переставил понедельник на пятницу. Никаких настоящих обвинений.",j("Дело о похищении последнего кусочка торта. Прокурор, ваша версия. Адвокат, ответьте. Обвиняемый, последнее слово."),j("Дело о слишком громком хрусте огурца. Стороны, представьте смешные аргументы."),j("Дело о самовольном продлении выходных. Какой безопасный приговор предложите?")),
  new Game("story","История по кругу","Каждый продолжает историю одним предложением. Организатор передаёт очередь. Один балл за участие по кнопке «Засчитать». Все события вымышлены.","Я нашёл чемодан, а внутри сидел очень деловой ёж. Следующий продолжает.",j("Утром Катя получила письмо: сегодня её назначили министром отличного настроения. Продолжите по кругу."),j("В доме появился лифт, который ездил только в прошлое лето. Что произошло дальше?"),j("Праздничный торт вдруг попросил микрофон. Что он сказал?"))
 );}
 public static Game get(String id){for(Game g:all())if(g.id.equals(id))return g;return all().get(0);}
 public static String normal(String s){return s.toLowerCase(Locale.ROOT).replace('ё','е').replaceAll("[^\\p{L}\\p{N} ]"," ").replaceAll("\\s+"," ").trim();}
 public static boolean matches(String text,String alternatives){String t=" "+normal(text)+" ";for(String a:alternatives.split("\\|"))if(!a.isBlank()&&t.contains(" "+normal(a)+" "))return true;return false;}
}
